package jp.co.soramitsu.coredb.recovery.decision

import android.os.CancellationSignal
import androidx.sqlite.db.SimpleSQLiteQuery
import androidx.sqlite.db.SupportSQLiteDatabase
import jp.co.soramitsu.coredb.recovery.endpointInteger

/** The exact connection-local invalidation objects generated by Room 2.7.2 for schema 83. */
internal object EndpointRoomProjectionSchema {
    data class Object(val type: String, val name: String, val table: String, val sql: String)

    private const val LOG = "room_table_modification_log"
    private const val PREFIX = "room_table_modification_trigger_chain_nodes_"

    // AppDatabase_Impl's ordered invalidation table list binds chain_nodes to 9. The actual
    // Room-observer integration test must change with that generated contract, never silently.
    private const val TABLE_ID = 9
    private val expected = listOf(
        Object(
            "table", LOG, LOG,
            "CREATE TABLE room_table_modification_log (table_id INTEGER PRIMARY KEY, invalidated INTEGER NOT NULL DEFAULT 0)"
        )
    ) + listOf("DELETE", "INSERT", "UPDATE").map { operation ->
        Object(
            "trigger", PREFIX + operation, "chain_nodes",
            "CREATE TRIGGER `$PREFIX$operation` AFTER $operation ON `chain_nodes` BEGIN UPDATE $LOG " +
                "SET invalidated = 1 WHERE table_id = $TABLE_ID AND invalidated = 0; END"
        )
    }
    private val reserved = (listOf(LOG) + expected.drop(1).map { it.name }).joinToString(" OR ") {
        "name='$it' COLLATE NOCASE OR tbl_name='$it' COLLATE NOCASE"
    }

    /** Must run on the same writer connection and snapshot as the guarded projection mutation. */
    fun requireSchema(
        db: SupportSQLiteDatabase,
        signal: CancellationSignal,
        projectionNamespace: String
    ) {
        check(db.inTransaction())
        signal.throwIfCanceled()
        val objects = db.query(
            SimpleSQLiteQuery(
            "SELECT ${decisionTextProjection("type", 64)},${decisionTextProjection("name", 128)}," +
                "${decisionTextProjection("tbl_name", 128)},${decisionTextProjection("sql", 4096)} " +
                "FROM temp.sqlite_master WHERE ($projectionNamespace) OR ($reserved) LIMIT 5"
        ),
            signal
        ).use { cursor ->
            buildList {
                while (cursor.moveToNext()) {
                    signal.throwIfCanceled()
                    check(cursor.columnCount == 4 && size < 4) { "Endpoint temporary projection namespace differs" }
                    add(
                        Object(
                            cursor.decisionText(0, 64), cursor.decisionText(1, 128),
                        cursor.decisionText(2, 128), cursor.decisionText(3, 4096)
                        )
                    )
                }
            }
        }
        if (validateObjects(objects)) {
            db.query(
                SimpleSQLiteQuery(
                "SELECT table_id,invalidated FROM temp.$LOG WHERE table_id=$TABLE_ID LIMIT 2"
            ),
                signal
            ).use {
                signal.throwIfCanceled()
                check(
                    it.columnCount == 2 && it.moveToFirst() && it.endpointInteger(0) == TABLE_ID.toLong() &&
                    it.endpointInteger(1) in 0L..1L && !it.moveToNext()
                ) { "Endpoint Room tracking row differs" }
            }
        }
        signal.throwIfCanceled()
    }

    /** Empty standalone SQLite, idle Room, or all three exact Room hooks are the only admitted shapes. */
    fun validateObjects(objects: List<Object>): Boolean {
        check(objects.size == objects.map { it.name }.toSet().size) { "Endpoint temporary projection namespace is ambiguous" }
        val found = objects.toSet()
        check(found.isEmpty() || found == setOf(expected.first()) || found == expected.toSet()) {
            "Endpoint temporary projection namespace differs"
        }
        return found.size == expected.size
    }
}
